1	"use server";
2	
3	import { promises as fs } from "node:fs";
4	import { join } from "node:path";
5	import { spawn } from "node:child_process";
6	import { revalidatePath } from "next/cache";
7	import { db } from "./db";
8	import { requireAdmin } from "./auth";
9	
10	import { BOARD_UPLOAD_DIR, type StageAction } from "./board-shared";
11	
12	const DEFAULT_COLUMNS = ["Ideas", "Backlog", "In progress", "Review", "Done"];
13	
14	// Root of the deployed repo (where scripts/ lives). The web process runs from
15	// /opt/nxeon in production; process.cwd() is the safe, correct base for the
16	// relative script paths the pipeline actions invoke.
17	const PROJECT_ROOT = process.env.NXEON_PROJECT_ROOT ?? process.cwd();
18	const STAGE_LOG_DIR = join(BOARD_UPLOAD_DIR, "stage-logs");
19	
20	export type AppSummary = {
21	  id: string;
22	  name: string;
23	  slug: string;
24	  color: string | null;
25	  boardCount: number;
26	  // The real infrastructure Server this app is bound to, if any. Null = the app
27	  // is just a label (e.g. the Nxeon platform itself has no customer Server row).
28	  serverId: string | null;
29	  serverName: string | null;
30	  serverStatus: string | null;
31	  // ---- Working context: where this app's code lives + how to build/deploy it,
32	  // so a Claude session (or a human) can act on the right app. Edited via the
33	  // board's "App settings" panel; all optional. ----
34	  codePath: string | null;
35	  repoUrl: string | null;
36	  context: string | null;
37	};
38	export type ServerOption = { id: string; name: string; ipAddress: string | null; status: string };
39	export type BoardSummary = { id: string; name: string; cardCount: number; appId: string | null };
40	export type CardSummary = {
41	  id: string;
42	  title: string;
43	  type: string;
44	  priority: string;
45	  labels: string[];
46	  assignee: string | null;
47	  attachmentCount: number;
48	  commentCount: number;
49	  hasDescription: boolean;
50	  updatedAt: string;
51	};
52	export type CardSearchHit = {
53	  id: string;
54	  boardId: string;
55	  boardName: string;
56	  columnId: string;
57	  columnName: string;
58	  title: string;
59	  type: string;
60	  priority: string;
61	  snippet: string;
62	  matchedIn: "title" | "description" | "comment";
63	};
64	export type ColumnData = { id: string; name: string; position: number; cards: CardSummary[] };
65	export type BoardData = { id: string; name: string; columns: ColumnData[] };
66	export type CardDetail = CardSummary & {
67	  description: string;
68	  columnId: string;
69	  columnName: string;
70	  attachments: { id: string; filename: string; kind: string; mime: string; sizeBytes: number; url: string }[];
71	  comments: { id: string; authorName: string; body: string; createdAt: string }[];
72	};
73	
74	// ---- Apps ------------------------------------------------------------------
75	
76	function slugify(name: string): string {
77	  return name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "app";
78	}
79	
80	/** All apps/products, oldest first, with their board counts and bound server. */
81	export async function listApps(): Promise<AppSummary[]> {
82	  await requireAdmin();
83	  const apps = await db.app.findMany({
84	    orderBy: { createdAt: "asc" },
85	    include: { _count: { select: { boards: true } }, server: { select: { id: true, name: true, status: true } } },
