import re, subprocess

cand = subprocess.check_output(
    ['grep','-rl','use server','/opt/nxeon/lib','/opt/nxeon/app',
     '--include=*.ts','--include=*.tsx']).decode().split()

def is_action_file(src):
    # strip block comments
    s = re.sub(r'/\*.*?\*/', '', src, flags=re.S)
    # walk lines, skip blanks and // comments
    for line in s.splitlines():
        t=line.strip()
        if not t or t.startswith('//'):
            continue
        return bool(re.match(r'^["\']use server["\']\s*;?$', t))
    return False

action_files=[]
for f in cand:
    try: src=open(f,encoding='utf-8',errors='replace').read()
    except: continue
    if is_action_file(src): action_files.append(f)

AUTH = re.compile(r'\b(requireUser|requireAdmin|requireStaff|requireArea|realUser|currentUser|assertNotImpersonating)\b')
DANGER = re.compile(r'\.job\.create|\.hostingTask\.create|\bspawn\(|\bexecSync|(?<![a-zA-Z_.])exec\(|\bwriteFile|\bsshExec\b|withServerSsh|\brunRcon\b|runScopedSql|\.walletTransaction\.create|serverRootPassword|writeFileText|writeFileBuffer|removePath|mkdirPath|chmodPath|\.setting\.upsert|setSetting|\bredirect\(')
