INLINE_OWN2 = re.compile(r'userId:\s*(user|u|me)\.id')

def all_funcs(src):
    marks=[]
    for m in re.finditer(r'^(export\s+)?async\s+function\s+(\w+)\s*[\(<]', src, re.M):
        marks.append((m.group(2), m.start(), bool(m.group(1))))
    for m in re.finditer(r'^(export\s+)?const\s+(\w+)\s*=\s*async\s*(?:function)?\s*[\(<]', src, re.M):
        marks.append((m.group(2), m.start(), bool(m.group(1))))
    marks.sort(key=lambda x:x[1])
    out=[]
    for i,(name,pos,exp) in enumerate(marks):
        end = marks[i+1][1] if i+1 < len(marks) else len(src)
        out.append((name,pos,end,src[pos:end],exp))
    return out

print(f"# {len(action_files)} true action files\n")
print("=== DANGEROUS-SINK EXPORTED ACTIONS WITH NO AUTH/OWNERSHIP GUARD ===")
