    fns=all_funcs(src)
    guard_helpers={name for name,p,e,b,exp in fns if AUTH.search(b)}
    gc = re.compile(r'\b('+'|'.join(re.escape(g) for g in guard_helpers)+r')\s*\(') if guard_helpers else None
