685	  if (lt.mode === "sandbox") return { mode: "sandbox" };
686	  const vis = await tableIsVisible(lt.target, dbName, table);
687	  if ("error" in vis) return { error: vis.error };
688	  return { mode: "live", target: lt.target };
689	}
