1216	  const dark = probes.filter((p) => !p.serving);
1217	  const allServing = probes.length > 0 && dark.length === 0;
1218	  // Only ever UPGRADE the honest verdict — a re-check that finds everything live
1219	  // flips COMPLETED_WITH_ISSUES → DONE. Never downgrade (that belongs to the
1220	  // engine's own run, not a spot re-check).
1221	  if (allServing && currentStatus === "COMPLETED_WITH_ISSUES") {
1222	    await db.migration.update({
1223	      where: { id: migrationId },
1224	      data: { status: "DONE", step: "Completed — all sites serving" },
1225	    }).catch(() => {});
1226	  }
1227	  return allServing;
1228	}
