1230	/**
1231	 * Re-check (only) whether each site serves now, and flip the migration to DONE
1232	 * if they all do. No bring-up — just an honest re-probe. Cheap; safe to spam.
1233	 */
1234	export async function recheckMigrationServing(migrationId: string): Promise<RemediationResult> {
1235	  const ctx = await ownedMigrationForRemediation(migrationId);
1236	  if ("error" in ctx) return { error: ctx.error };
1237	  const { m, server, user } = ctx;
1238	  const rl = checkRateLimit(`migrate:recheck:${user.id}`, { max: 20, windowMs: 5 * 60 * 1000 });
1239	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before checking again.` };
1240	  const domains = migrationProbeDomains(m.items);
1241	  if (!domains.length) return { ok: true, serving: [], dark: [], allServing: false, log: ["No domains to check."] };
1242	  if (SANDBOX) {
1243	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended all sites serve."] };
1244	  }
1245	  try {
1246	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1247	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1248	    revalidatePath("/dashboard/migrate");
1249	    return {
1250	      ok: true,
1251	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1252	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1253	      allServing,
1254	    };
1255	  } catch {
1256	    return { error: "Couldn't reach the new server to check. Try again in a moment." };
1257	  }
1258	}
