1260	/**
1261	 * Finish the migration the customer couldn't: bring up any copied compose stacks,
1262	 * start the units the engine created (incl. the reproduced pm2/manual-start
1263	 * apps), reload nginx, then re-probe. Everything here is idempotent and
1264	 * TARGET-side; it never touches the old server and never removes anything.
1265	 */
1266	export async function finishMigrationSetup(migrationId: string): Promise<RemediationResult> {
1267	  const ctx = await ownedMigrationForRemediation(migrationId);
1268	  if ("error" in ctx) return { error: ctx.error };
1269	  const { m, server, user } = ctx;
1270	  const rl = checkRateLimit(`migrate:finish:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
1271	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before trying again.` };
1272	  const domains = migrationProbeDomains(m.items);
1273	  const composeDirs = (((m.items ?? {}) as { composeDirs?: unknown[] }).composeDirs ?? [])
1274	    .map((p) => String(p ?? ""))
1275	    .filter((p) => REMEDIATE_PATH_RE.test(p))
1276	    .slice(0, 20);
1277	  if (SANDBOX) {
1278	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended to finish setup."] };
1279	  }
1280	  const log: string[] = [];
1281	  try {
1282	    await withServerSsh(server, async (conn) => {
1283	      // 1. Bring up copied compose stacks (idempotent; -f for non-default names).
1284	      for (const dir of composeDirs) {
1285	        const cf = (
1286	          await exec(conn, `for f in ${REMEDIATE_COMPOSE_FILES}; do [ -f ${dir}/$f ] && { echo ${dir}/$f; break; }; done`, 15000)
1287	        ).stdout.trim();
1288	        if (!REMEDIATE_PATH_RE.test(cf)) continue;
1289	        const fArg = /\/(docker-compose|compose)\.ya?ml$/.test(cf) ? "" : `-f ${cf} `;
1290	        const r = await exec(conn, `sh -c 'cd ${dir} && docker compose ${fArg}up -d' 2>&1 | tail -2`, 300000);
1291	        log.push(`Started ${dir.split("/").pop()}: ${r.stdout.trim().slice(0, 100) || "ok"}`);
1292	      }
1293	      // 2. Start the units the engine created that aren't running yet.
1294	      await exec(
1295	        conn,
1296	        `for u in $(systemctl list-unit-files 'nxeon-app-*.service' --no-legend 2>/dev/null | awk '{print $1}'); do systemctl start "$u" 2>/dev/null || true; done`,
1297	        60000
1298	      );
1299	      // 3. Reload nginx if its config is valid.
1300	      await exec(conn, `nginx -t >/dev/null 2>&1 && systemctl reload nginx 2>/dev/null || true`, 30000);
1301	      log.push("Reloaded the web server.");
1302	    });
1303	    // 4. Give the just-started apps a moment, then probe honestly.
1304	    await new Promise((r) => setTimeout(r, 12000));
1305	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1306	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1307	    revalidatePath("/dashboard/migrate");
1308	    return {
1309	      ok: true,
1310	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1311	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1312	      allServing,
1313	      log,
1314	    };
1315	  } catch {
1316	    return { error: "Couldn't finish setup on the new server. Your old server is still serving — try again shortly." };
1317	  }
1318	}
