71	async function agentRequest(
72	  node: AgentNode,
73	  method: "GET" | "POST" | "DELETE",
74	  path: string,
75	  body?: unknown
76	): Promise<any> {
77	  const token = nodeAgentToken(node);
78	  if (!token) {
79	    throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
80	  }
81	  const url = `https://${node.publicIp}:${node.agentPort}${path}`;
82	  const doFetch = () =>
83	    undiciFetch(url, {
84	      method,
85	      headers: {
86	        Authorization: `Bearer ${token}`,
87	        ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
88	      },
89	      body: body !== undefined ? JSON.stringify(body) : undefined,
90	      dispatcher: insecureAgent,
91	      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
92	    });
93	  let res: Awaited<ReturnType<typeof doFetch>>;
94	  try {
95	    res = await doFetch();
96	  } catch (e: any) {
97	    throw new NodeAgentError(`could not reach node-agent on "${node.name}" (${url}): ${e?.message ?? e}`, node.name);
98	  }
99	  const text = await res.text().catch(() => "");
100	  if (!res.ok) {
101	    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status}: ${text.slice(0, 300)}`, node.name);
102	  }
103	  if (!text) return null;
104	  try {
105	    return JSON.parse(text);
106	  } catch {
107	    throw new NodeAgentError(`node-agent on "${node.name}" returned a non-JSON response: ${text.slice(0, 200)}`, node.name);
108	  }
109	}
